    std::uint8_t *aEarthLaneB = pWorkSpace->mEarthLaneB;
    std::uint8_t *aEarthLaneC = pWorkSpace->mEarthLaneC;
    std::uint8_t *aEarthLaneD = pWorkSpace->mEarthLaneD;
    std::uint64_t aCross = 0; std::uint64_t aScatter = 0;

    std::uint64_t aOrbiterA = 0; std::uint64_t aOrbiterB = 0; std::uint64_t aOrbiterC = 0; std::uint64_t aOrbiterD = 0;
    std::uint64_t aOrbiterE = 0; std::uint64_t aOrbiterF = 0; std::uint64_t aOrbiterG = 0; std::uint64_t aOrbiterH = 0;
    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [kdf-a arx]
    const std::uint64_t aNonceWordA = TwistMix64::DiffuseB(pNonce * 0xB7512D9768FCE74FULL + 0xC513901B31A13DA2ULL);
    const std::uint64_t aNonceWordB = TwistMix64::DiffuseC(pNonce * 0xE7D7C59E0AEE1141ULL + 0xC86E0FC28558F790ULL);
    const std::uint64_t aNonceWordC = TwistMix64::DiffuseB(pNonce * 0xCEB12321D343CEF5ULL + 0xDC1836ECE5541989ULL);
    const std::uint64_t aNonceWordD = TwistMix64::DiffuseA(pNonce * 0x9D56A935357B9589ULL + 0xE135FC3677AF2628ULL);
    const std::uint64_t aNonceWordE = TwistMix64::DiffuseB(pNonce * 0xB28E581F719E3B2DULL + 0xADA7B95A8A2A77A6ULL);
    const std::uint64_t aNonceWordF = TwistMix64::DiffuseA(pNonce * 0xBEBD2D5AE403AA13ULL + 0xEBB408E04832465FULL);
    const std::uint64_t aNonceWordG = TwistMix64::DiffuseB(pNonce * 0x80EC25C2B1BADBCBULL + 0x9E91277F5B46E911ULL);
    const std::uint64_t aNonceWordH = TwistMix64::DiffuseC(pNonce * 0xBFA2D54C74159B27ULL + 0xBA79062D4337574BULL);
    const std::uint64_t aNonceWordI = TwistMix64::DiffuseC(pNonce * 0xC5920CD05E104773ULL + 0xAE652A7B73A129D4ULL);
    const std::uint64_t aNonceWordJ = TwistMix64::DiffuseA(pNonce * 0xAA8AD130C65ECC61ULL + 0xBAD3F39173A2C387ULL);
    const std::uint64_t aNonceWordK = TwistMix64::DiffuseB(pNonce * 0xC281736EBB376B35ULL + 0xA4C56B2530B59B6EULL);
    const std::uint64_t aNonceWordL = TwistMix64::DiffuseA(pNonce * 0x96B36ACDF9CD309BULL + 0xD36528BCC0AA2130ULL);
    const std::uint64_t aNonceWordM = TwistMix64::DiffuseA(pNonce * 0x80A30A05952BFDC7ULL + 0xA0DDEA29936C1ECFULL);
    const std::uint64_t aNonceWordN = TwistMix64::DiffuseB(pNonce * 0x8D3E87022C71E04FULL + 0xBDF30D02C156F87FULL);
    const std::uint64_t aNonceWordO = TwistMix64::DiffuseB(pNonce * 0xCBF9E110E49D1BA7ULL + 0xC7C81FEC4C408C04ULL);
