            aOrbiterI = (aWandererF + RotL64(aIngress, 60U)) + 0x49C9EC68B97BACA2ULL;
            aOrbiterC = (aWandererJ + RotL64(aScatter, 27U)) + 0x0B72AB4CE9C5D5B6ULL;
            aOrbiterB = ((aWandererA + RotL64(aPrevious, 23U)) + 0xBCB965B9CAECAA20ULL) + aNonceWordI;
            aOrbiterE = ((aWandererC + RotL64(aCross, 41U)) + RotL64(aCarry, 37U)) + 0xF1A97560652A033DULL;
            aOrbiterG = ((aWandererH + RotL64(aIngress, 57U)) + 0x07DD89B44B57373CULL) + aOASaltF[(((511U - aIndex) + 476U)) & S_SALT1];
            aOrbiterA = (((aWandererG + RotL64(aScatter, 3U)) + 0x49CD330732D2E587ULL) + aOASaltG[(((511U - aIndex) + 454U)) & S_SALT1]) + aNonceWordL;
            aOrbiterH = ((aWandererD + RotL64(aPrevious, 30U)) + RotL64(aCarry, 19U)) + 0x5B7E7BB79745331CULL;
            //
            aOrbiterK = (aOrbiterK + aOrbiterJ) + 0xCF73BF7DAB68971DULL;
