            aScatter = (RotL64(aCarry, 27U) + RotL64(aIngress, 39U)) + (RotL64(aPrevious, 14U) ^ RotL64(aCross, 53U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterG = (aWandererE + RotL64(aIngress, 51U)) + 0xEC1AC133DB122FC0ULL;
            aOrbiterD = (aWandererA + RotL64(aScatter, 3U)) + 0x67BA0DAFBA6EC087ULL;
            aOrbiterC = ((aWandererB + RotL64(aPrevious, 48U)) + 0xE92E666F6A65CD93ULL) + aOASaltC[((aIndex + 287U)) & S_SALT1];
