            aWandererA = aWandererA ^ ((((RotL64(aScatter, 47U) + aOrbiterC) + RotL64(aOrbiterA, 30U)) + RotL64(aCarry, 19U)) + aWUSaltC[(((511U - aIndex) + 97U)) & S_SALT1]);
            //
